def decode_string(s: str) -> str:
    stack = []
    num = 0
    current = ""

    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == '[':
            stack.append((current, num))
            current = ""
            num = 0
        elif ch == ']':
            prev, repeat = stack.pop()
            current = prev + current * repeat
        else:
            current += ch

    return current
```

