def simplify_path(path: str) -> str:
    """
    Canonicalise an absolute Unix path.

    - Collapses repeated slashes.
    - Resolves '.' and '..' components.
    - '...' is treated as a normal directory/file name.
    - Returns the path without a trailing slash (except for root '/').
    """
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack)
