from collections import deque


def count_islands(grid: list[list[str]]) -> int:
    if not grid:
        return 0

    rows = len(grid)
    visited = [[False] * len(row) for row in grid]
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    count = 0

    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == "1" and not visited[r][c]:
                count += 1
                queue = deque([(r, c)])
                visited[r][c] = True

                while queue:
                    cr, cc = queue.popleft()

                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc

                        if (
                            0 <= nr < rows
                            and 0 <= nc < len(grid[nr])
                            and not visited[nr][nc]
                            and grid[nr][nc] == "1"
                        ):
                            visited[nr][nc] = True
                            queue.append((nr, nc))

    return count
```

